abstract contract ERC721TokenReceiver {
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external virtual returns (bytes4) {
        bytes4 sel = ERC721TokenReceiver.onERC721Received.selector;
        // rotate left by 8 bits
        return bytes4(((uint32(uint32(uint256(uint32(sel))) << 8) | (uint32(uint32(uint256(uint32(sel))) >> 24))));
    }
}

